                best_match = cat

        if best_match:
            # Clean up the name
            name = best_match.strip('"').strip()
            # Limit words
            words = name.split()
            if len(words) > max_words:
                name = ' '.join(words[:max_words])
            # Use | as separator
            name = name.replace(' ', ' | ')
            return name

        # Fallback: use most common words
        return ' | '.join(common_words[:max_words])

    def build_unified_taxonomy(self):
        """Build the unified 5-level taxonomy."""
        print("\nBuilding unified taxonomy...")

        # Parse all category paths
        all_paths = []
        for source, categories in self.source_categories.items():
            for cat_path in categories:
                parsed = self.parse_category_path(cat_path)
                if parsed:
                    all_paths.append({
                        'source': source,
                        'original': cat_path,
                        'parsed': parsed,
                        'depth': len(parsed)
                    })

        # Extract all unique categories at each level
        level_categories = defaultdict(lambda: defaultdict(list))

        for path_info in all_paths:
            parsed = path_info['parsed']
            source = path_info['source']

            for level_idx, category in enumerate(parsed[:5]):  # Only use first 5 levels
                level_categories[level_idx][self.normalize_text(category)].append({
                    'original': category,
                    'source': source,
                    'full_path': parsed
                })

        # Build level 1 (top level: 10-20 broad categories)
        print("Building Level 1 categories...")
        level1_clusters = self._cluster_categories(level_categories[0], target_count=15)

        # Build subsequent levels
        taxonomy_tree = {}

        for l1_name, l1_items in level1_clusters.items():
            taxonomy_tree[l1_name] = {
                'items': l1_items,
                'children': {}
            }

            # Get categories that belong to this L1
            l1_paths = []
            for item in l1_items:
                for path_info in all_paths:
                    if len(path_info['parsed']) > 0:
                        if self.normalize_text(path_info['parsed'][0]) == self.normalize_text(item['original']):
                            l1_paths.append(path_info)

            # Build Level 2
            l2_cats = defaultdict(list)
            for path_info in l1_paths:
                if len(path_info['parsed']) > 1:
                    cat = path_info['parsed'][1]
                    l2_cats[self.normalize_text(cat)].append({
                        'original': cat,
                        'source': path_info['source'],
                        'full_path': path_info['parsed']
                    })

            if l2_cats:
                l2_clusters = self._cluster_categories(l2_cats, target_count=10, min_count=3, max_count=20)
                taxonomy_tree[l1_name]['children'] = {}

                for l2_name, l2_items in l2_clusters.items():
                    taxonomy_tree[l1_name]['children'][l2_name] = {
                        'items': l2_items,
                        'children': {}
                    }

                    # Build Level 3
                    l2_paths = []
                    for item in l2_items:
                        for path_info in l1_paths:
                            if len(path_info['parsed']) > 1:
                                if self.normalize_text(path_info['parsed'][1]) == self.normalize_text(item['original']):
                                    l2_paths.append(path_info)

                    l3_cats = defaultdict(list)
                    for path_info in l2_paths:
                        if len(path_info['parsed']) > 2:
                            cat = path_info['parsed'][2]
                            l3_cats[self.normalize_text(cat)].append({
                                'original': cat,
                                'source': path_info['source'],
                                'full_path': path_info['parsed']
                            })

                    if l3_cats:
                        l3_clusters = self._cluster_categories(l3_cats, target_count=8, min_count=3, max_count=20)

                        for l3_name, l3_items in l3_clusters.items():
                            taxonomy_tree[l1_name]['children'][l2_name]['children'][l3_name] = {
                                'items': l3_items,
                                'children': {}
                            }

                            # Build Level 4
                            l3_paths = []
                            for item in l3_items:
                                for path_info in l2_paths:
                                    if len(path_info['parsed']) > 2:
                                        if self.normalize_text(path_info['parsed'][2]) == self.normalize_text(item['original']):
                                            l3_paths.append(path_info)

                            l4_cats = defaultdict(list)
                            for path_info in l3_paths:
                                if len(path_info['parsed']) > 3:
                                    cat = path_info['parsed'][3]
                                    l4_cats[self.normalize_text(cat)].append({
                                        'original': cat,
                                        'source': path_info['source'],
                                        'full_path': path_info['parsed']
                                    })

                            if l4_cats:
                                l4_clusters = self._cluster_categories(l4_cats, target_count=7, min_count=3, max_count=20)

                                for l4_name, l4_items in l4_clusters.items():
                                    taxonomy_tree[l1_name]['children'][l2_name]['children'][l3_name]['children'][l4_name] = {
                                        'items': l4_items,
                                        'children': {}
                                    }

                                    # Build Level 5
                                    l4_paths = []
                                    for item in l4_items:
                                        for path_info in l3_paths:
                                            if len(path_info['parsed']) > 3:
                                                if self.normalize_text(path_info['parsed'][3]) == self.normalize_text(item['original']):
                                                    l4_paths.append(path_info)

                                    l5_cats = defaultdict(list)
                                    for path_info in l4_paths:
                                        if len(path_info['parsed']) > 4:
                                            cat = path_info['parsed'][4]
                                            l5_cats[self.normalize_text(cat)].append({
                                                'original': cat,
                                                'source': path_info['source'],
                                                'full_path': path_info['parsed']
                                            })

                                    if l5_cats:
                                        l5_clusters = self._cluster_categories(l5_cats, target_count=6, min_count=3, max_count=20)
                                        taxonomy_tree[l1_name]['children'][l2_name]['children'][l3_name]['children'][l4_name]['children'] = {
                                            name: {'items': items, 'children': {}}
                                            for name, items in l5_clusters.items()
                                        }

        self.taxonomy_tree = taxonomy_tree
        self._print_taxonomy_stats()

    def _cluster_categories(self, categories: Dict, target_count=10, min_count=3, max_count=20) -> Dict:
        """Cluster similar categories together."""
        if not categories:
            return {}

        # Sort by frequency
        sorted_cats = sorted(categories.items(), key=lambda x: len(x[1]), reverse=True)

        clusters = {}
        used = set()

        # Start with most frequent categories as cluster seeds
        for norm_name, items in sorted_cats:
            if norm_name in used:
                continue

            if len(clusters) >= max_count:
                break

            # Create cluster with this category
            cluster_items = list(items)
            used.add(norm_name)

            # Try to merge similar categories
            for other_norm, other_items in sorted_cats:
                if other_norm in used:
                    continue

                # Check similarity
                overlap = self.calculate_word_overlap(norm_name, other_norm)

                if overlap > 0.5:  # High similarity threshold
                    cluster_items.extend(other_items)
                    used.add(other_norm)

            # Create representative name
            original_names = [item['original'] for item in cluster_items]
            cluster_name = self.create_category_name(original_names)

            # Make sure name doesn't have too much overlap with siblings
            is_valid = True
            for existing_name in clusters.keys():
                if self.calculate_word_overlap(cluster_name, existing_name) > 0.3:
                    # Try to make it more specific
                    cluster_name = self._make_name_distinct(cluster_name, existing_name, original_names)

            clusters[cluster_name] = cluster_items

        # If we have too few clusters, split the largest ones
        while len(clusters) < min_count and len(clusters) > 0:
            largest_cluster = max(clusters.items(), key=lambda x: len(x[1]))
            if len(largest_cluster[1]) < 4:
                break

            # Split this cluster
            del clusters[largest_cluster[0]]
            mid = len(largest_cluster[1]) // 2

            items1 = largest_cluster[1][:mid]
            items2 = largest_cluster[1][mid:]

            name1 = self.create_category_name([item['original'] for item in items1])
            name2 = self.create_category_name([item['original'] for item in items2])

            clusters[name1] = items1
            clusters[name2] = items2

        return clusters

    def _make_name_distinct(self, name1: str, name2: str, original_names: List[str]) -> str:
        """Make a category name more distinct from another."""
        # Try to find words that are unique
        words1 = set(name1.lower().split(' | '))
        words2 = set(name2.lower().split(' | '))

        unique_words = words1 - words2

        if unique_words:
            # Rebuild name with unique words first
            all_words = name1.split(' | ')
            unique_first = [w for w in all_words if w.lower() in unique_words]
            other_words = [w for w in all_words if w.lower() not in unique_words]
            return ' | '.join((unique_first + other_words)[:5])

        return name1

    def _print_taxonomy_stats(self):
        """Print statistics about the taxonomy."""
        print("\nTaxonomy Statistics:")
        print(f"Level 1 categories: {len(self.taxonomy_tree)}")

        l2_counts = []
        l3_counts = []
        l4_counts = []
        l5_counts = []

        for l1_name, l1_node in self.taxonomy_tree.items():
            l2_count = len(l1_node['children'])
            l2_counts.append(l2_count)

            for l2_name, l2_node in l1_node['children'].items():
                l3_count = len(l2_node['children'])
                l3_counts.append(l3_count)

                for l3_name, l3_node in l2_node['children'].items():
                    l4_count = len(l3_node['children'])
                    l4_counts.append(l4_count)

                    for l4_name, l4_node in l3_node['children'].items():
                        l5_count = len(l4_node['children'])
                        l5_counts.append(l5_count)

        if l2_counts:
            print(f"Level 2: avg={sum(l2_counts)/len(l2_counts):.1f}, min={min(l2_counts)}, max={max(l2_counts)}")
        if l3_counts:
            print(f"Level 3: avg={sum(l3_counts)/len(l3_counts):.1f}, min={min(l3_counts)}, max={max(l3_counts)}")
        if l4_counts:
            print(f"Level 4: avg={sum(l4_counts)/len(l4_counts):.1f}, min={min(l4_counts)}, max={max(l4_counts)}")
        if l5_counts:
            print(f"Level 5: avg={sum(l5_counts)/len(l5_counts):.1f}, min={min(l5_counts)}, max={max(l5_counts)}")

    def map_original_categories(self):
        """Map original categories to unified taxonomy."""
        print("\nMapping original categories to unified taxonomy...")

        self.category_mapping = []

        for source, categories in self.source_categories.items():
            for cat_path in categories:
                parsed = self.parse_category_path(cat_path)
                if not parsed:
                    continue

                # Find best match in taxonomy tree
                unified_levels = self._find_best_match(parsed)

                mapping = {
                    'source': source,
                    'category_path': cat_path,
                    'depth': len(parsed),
                    'unified_level_1': unified_levels[0] if len(unified_levels) > 0 else '',
                    'unified_level_2': unified_levels[1] if len(unified_levels) > 1 else '',
                    'unified_level_3': unified_levels[2] if len(unified_levels) > 2 else '',
                    'unified_level_4': unified_levels[3] if len(unified_levels) > 3 else '',
                    'unified_level_5': unified_levels[4] if len(unified_levels) > 4 else '',
                }

                self.category_mapping.append(mapping)

        print(f"Mapped {len(self.category_mapping)} categories")

    def _find_best_match(self, parsed_path: List[str]) -> List[str]:
        """Find best matching path in unified taxonomy."""
        unified_path = []

        # Match Level 1
        best_l1 = self._find_best_match_at_level(
            parsed_path[0] if len(parsed_path) > 0 else '',
            list(self.taxonomy_tree.keys())
        )

        if not best_l1:
            return unified_path

        unified_path.append(best_l1)

        # Match Level 2
        if len(parsed_path) > 1 and best_l1 in self.taxonomy_tree:
            l2_options = list(self.taxonomy_tree[best_l1]['children'].keys())
            best_l2 = self._find_best_match_at_level(parsed_path[1], l2_options)

            if best_l2:
                unified_path.append(best_l2)

                # Match Level 3
                if len(parsed_path) > 2:
                    l3_options = list(self.taxonomy_tree[best_l1]['children'][best_l2]['children'].keys())
                    best_l3 = self._find_best_match_at_level(parsed_path[2], l3_options)

                    if best_l3:
                        unified_path.append(best_l3)

                        # Match Level 4
                        if len(parsed_path) > 3:
                            l4_options = list(self.taxonomy_tree[best_l1]['children'][best_l2]['children'][best_l3]['children'].keys())
                            best_l4 = self._find_best_match_at_level(parsed_path[3], l4_options)

                            if best_l4:
                                unified_path.append(best_l4)

                                # Match Level 5
                                if len(parsed_path) > 4:
                                    l5_options = list(self.taxonomy_tree[best_l1]['children'][best_l2]['children'][best_l3]['children'][best_l4]['children'].keys())
                                    best_l5 = self._find_best_match_at_level(parsed_path[4], l5_options)

                                    if best_l5:
                                        unified_path.append(best_l5)

        return unified_path

    def _find_best_match_at_level(self, category: str, options: List[str]) -> str:
        """Find best matching category from options."""
        if not options or not category:
            return ''

        best_match = None
        best_score = 0

        for option in options:
            # Calculate similarity
            score = self.calculate_word_overlap(category, option)

            if score > best_score:
                best_score = score
                best_match = option

        return best_match if best_match else (options[0] if options else '')

    def generate_outputs(self, output_dir='/root/output'):
        """Generate output CSV files."""
        print("\nGenerating output files...")

        os.makedirs(output_dir, exist_ok=True)

        # Generate unified_taxonomy_full.csv
        with open(f'{output_dir}/unified_taxonomy_full.csv', 'w', newline='', encoding='utf-8') as f:
            fieldnames = ['source', 'category_path', 'depth',
                         'unified_level_1', 'unified_level_2', 'unified_level_3',
                         'unified_level_4', 'unified_level_5']
            writer = csv.DictWriter(f, fieldnames=fieldnames)
            writer.writeheader()

            for mapping in self.category_mapping:
                writer.writerow(mapping)

        print(f"Generated {output_dir}/unified_taxonomy_full.csv")

        # Generate unified_taxonomy_hierarchy.csv
        hierarchy_paths = set()

        def traverse_tree(tree, path=[]):
            """Recursively traverse tree to collect all paths."""
            for node_name, node_data in tree.items():
                current_path = path + [node_name]

                # Add this path
                while len(current_path) < 5:
                    current_path.append('')
                hierarchy_paths.add(tuple(current_path[:5]))

                # Recurse into children
                if node_data.get('children'):
                    traverse_tree(node_data['children'], path + [node_name])

        traverse_tree(self.taxonomy_tree)

        # Sort paths for better organization
        sorted_paths = sorted(hierarchy_paths)

        with open(f'{output_dir}/unified_taxonomy_hierarchy.csv', 'w', newline='', encoding='utf-8') as f:
            fieldnames = ['unified_level_1', 'unified_level_2', 'unified_level_3',
                         'unified_level_4', 'unified_level_5']
            writer = csv.DictWriter(f, fieldnames=fieldnames)
            writer.writeheader()

            for path in sorted_paths:
                writer.writerow({
                    'unified_level_1': path[0],
                    'unified_level_2': path[1],
                    'unified_level_3': path[2],
                    'unified_level_4': path[3],
                    'unified_level_5': path[4],
                })

        print(f"Generated {output_dir}/unified_taxonomy_hierarchy.csv")
        print(f"Total hierarchy paths: {len(hierarchy_paths)}")

        # Print source distribution
        source_counts = defaultdict(int)
        for mapping in self.category_mapping:
            source_counts[mapping['source']] += 1

        print("\nSource distribution in unified taxonomy:")
        for source, count in source_counts.items():
            print(f"  {source}: {count}")


